class ClassFactory{static createCharacter(e,r,a,s,t){switch(e.toLowerCase()){case"warrior":return new WarriorPlayer(r,a,s,t);case"rogue":return new RoguePlayer(r,a,s,t);case"mage":return new MagePlayer(r,a,s,t);default:throw new Error(`Unknown character class: ${e}`)}}static getAvailableClasses(){return["Warrior","Rogue","Mage"]}static isClassImplemented(e){return this.getAvailableClasses().includes(e)}}